package com.company.kanban.controller;
import com.company.kanban.dto.TaskCheckpointSummaryResponse;import com.company.kanban.entity.User;import com.company.kanban.service.TaskCheckpointSummaryService;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/tasks/checkpoints") public class TaskCheckpointSummaryController { private final TaskCheckpointSummaryService service; public TaskCheckpointSummaryController(TaskCheckpointSummaryService service){this.service=service;} @GetMapping("/summary") public List<TaskCheckpointSummaryResponse> summaries(@RequestParam List<Long> taskIds,@AuthenticationPrincipal User user){return service.summaries(taskIds,user);} }
